using GraphApi.Models.ARC.LogVisualizacionArchivos;namespace GraphApi.Services.ARC.LogVisualizacionArchivos{    /// <summary>    /// Define las operaciones de negocio y persistencia para LogVisualizacionArchivos.    /// </summary>    public interface ILogVisualizacionArchivosService    {        /// <summary>        /// Obtiene la lista de LogVisualizacionArchivos con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadLogVisualizacionArchivos>> GetLogVisualizacionArchivos(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de LogVisualizacionArchivos con filtros opcionales.        /// </summary>        /// <param name="logVisualizacionArchivoID">Filtro opcional para LogVisualizacionArchivoID.</param>        /// <param name="archivoID">Filtro opcional para ArchivoID.</param>        /// <param name="usuarioID">Filtro opcional para UsuarioID.</param>        /// <param name="medio">Filtro opcional para Medio.</param>        /// <param name="iPOrigen">Filtro opcional para IPOrigen.</param>        /// <param name="userAgent">Filtro opcional para UserAgent.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetLogVisualizacionArchivosDynamic(            int? logVisualizacionArchivoID,            int? archivoID,            int? usuarioID,            string? medio,            string? iPOrigen,            string? userAgent,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo LogVisualizacionArchivo.        /// </summary>        /// <param name="objInput">Datos para crear el LogVisualizacionArchivo.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadLogVisualizacionArchivos> CreateLogVisualizacionArchivos(            clCreateLogVisualizacionArchivos objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un LogVisualizacionArchivo.        /// </summary>        /// <param name="objInput">Datos para actualizar el LogVisualizacionArchivo, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadLogVisualizacionArchivos?> UpdateLogVisualizacionArchivos(            clUpdateLogVisualizacionArchivos objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un LogVisualizacionArchivo por su ID.        /// </summary>        /// <param name="nLogVisualizacionArchivosID">ID del LogVisualizacionArchivo a eliminar.</param>        Task<bool> DeleteLogVisualizacionArchivos(int nLogVisualizacionArchivosID);    }}